    /// Recalls a memory pack.
    ///
    /// The lease the engine takes is not a client input, and a bearer slip
    /// is not one. Embedded, `Effort::High`, `XHigh` and `Max` return the
    /// engine's `LEASE_REQUIRED`: this client mints no lease. Remote, the
    /// server admits them on a line of its own and reranks on its `[models]`
    /// reranker, or runs them unreranked and says so when it has none.
    /// `media` is embedded by the server into its declared space; embedded,
    /// it returns `MODEL_UNAVAILABLE`. `query_affect` (valence in -1..=1,
    /// arousal and dominance in 0..=1) ranks by emotion congruence, embedded
    /// and remote alike; out of range it returns `BAD_REQUEST`.
    /// Explicit `scope.world_ref` recalls of retained foreign worlds carry
    /// `MemoryItem::stale`: stale-since and age in seconds (when known), the
    /// terminal reason and pact epoch. This selection grants no read authority.
    #[expect(
        clippy::too_many_arguments,
        reason = "one parameter per SDK argument of the verb"
    )]
    pub fn vault_recall(
        &self,
        query: &str,
        effort: oneiron::memory::RecallEffort,
        scope: &oneiron::memory::RecallScope,
        limit: usize,
        format: Option<&str>,
        as_of: Option<u64>,
        deadline_ms: Option<u64>,
        media: Option<oneiron::code_run::vault_read::ContextPackMediaQuery>,
        query_affect: Option<oneiron::task_verb::sdk::QueryAffect>,
    ) -> Result<oneiron::memory::MemoryPack, MemoryError> {
        let input = oneiron::task_verb::sdk::RecallRequest {
            query: query.to_owned(),
            effort: Some(effort),
            scope: Some(scope.clone()),
            limit: Some(limit),
            format: format.map(str::to_owned),
            as_of,
            deadline_ms,
            media,
            query_affect,
            ..Default::default()
        };
        oneiron::memory::caps::check_query(&input.query)?;
        oneiron::memory::caps::check_limit_nonzero(
            input
                .limit
                .unwrap_or(oneiron::task_verb::sdk::VAULT_RECALL_LIMIT_DEFAULT),
        )?;
        oneiron::memory::caps::check_as_of(input.as_of)?;
        oneiron::memory::caps::check_deadline_ms(input.deadline_ms)?;
        let value = serde_json::to_value(&input).map_err(|_| {
            crate::error::bad_request(
                "SDK input encoding failed",
                &["Send the documented typed SDK input."],
            )
        })?;
        self.typed_agent_verb("vault.recall", value)
    }
